schema:
CREATE TABLE IF NOT EXISTS budgets (
 id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, name VARCHAR(120) NOT NULL,
 category_id INTEGER NOT NULL, currency CHAR(3) NOT NULL, limit_minor BIGINT NOT NULL,
 start_on DATE NOT NULL, end_on DATE NOT NULL, threshold INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS goals (
 id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, name VARCHAR(120) NOT NULL,
 currency CHAR(3) NOT NULL, target_minor BIGINT NOT NULL, saved_minor BIGINT NOT NULL DEFAULT 0,
 deadline DATE NOT NULL, active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS goal_contributions (
 id INTEGER PRIMARY KEY AUTO_INCREMENT, goal_id INTEGER NOT NULL, amount_minor BIGINT NOT NULL,
 created_on DATE NOT NULL, FOREIGN KEY(goal_id) REFERENCES goals(id)
);
CREATE TABLE IF NOT EXISTS alerts (
 id INTEGER PRIMARY KEY AUTO_INCREMENT, budget_id INTEGER NOT NULL, threshold INTEGER NOT NULL,
 UNIQUE(budget_id,threshold), FOREIGN KEY(budget_id) REFERENCES budgets(id)
);
